<template>
  <main class="hh-page appointment-control">
    <section class="control-hero">
      <div><span>CONSULTA EXTERNA</span><h1>{{ config.title }}</h1><p>{{ config.help }}</p></div>
      <div><router-link to="/consulta-externa/agenda" class="btn btn-outline-light"><i class="ph ph-calendar me-1"></i>Agenda</router-link><button class="btn btn-light text-primary" :disabled="loading" @click="load"><i class="ph ph-arrows-clockwise me-1"></i>Actualizar</button></div>
    </section>
    <nav class="control-nav"><router-link to="/consulta-externa/solicitudes"><i class="ph ph-inbox"></i>Solicitudes</router-link><router-link to="/consulta-externa/no-atendidas"><i class="ph ph-user-minus"></i>No atendidas</router-link><router-link to="/mi-agenda"><i class="ph ph-stethoscope"></i>Mi agenda clínica</router-link></nav>
    <div v-if="mode==='professional'" class="btn-group mt-3"><button class="btn" :class="professionalSource==='appointments'?'btn-primary':'btn-outline-primary'" @click="professionalSource='appointments';load()">Citas programadas</button><button class="btn" :class="professionalSource==='clinical'?'btn-primary':'btn-outline-primary'" @click="professionalSource='clinical';load()">Actividades clínicas</button></div>
    <section v-if="mode==='professional'" class="filters"><template v-if="professionalSource==='appointments'"><input v-model="filters.desde" type="date" class="form-control"><input v-model="filters.hasta" type="date" :min="filters.desde" class="form-control"></template><template v-else><select v-model="filters.estado" class="form-select" @change="load"><option value="hoy">Actividades de hoy</option><option value="pendientes">Pendientes</option><option value="vencidas">Vencidas</option><option value="programadas">Programadas</option><option value="sin_programar">Sin programar</option><option value="realizadas">Realizadas</option><option value="todas">Todas</option></select><input v-model.trim="filters.buscar" class="form-control" placeholder="Paciente, servicio u orden" @keyup.enter="load"></template><button class="btn btn-primary" @click="load">Buscar</button></section>
    <div v-if="error" class="alert alert-danger mt-3">{{ error }}</div>
    <div v-if="notice" class="alert alert-success mt-3">{{ notice }}</div>
    <div v-if="loading" class="loading"><span class="spinner-border text-primary"></span><p>Consultando información…</p></div>
    <section v-else class="control-list">
      <div v-if="!items.length" class="empty"><i :class="config.icon"></i><h3>{{ config.empty }}</h3><p>No hay registros para gestionar en este momento.</p></div>
      <article v-for="item in items" :key="itemId(item)">
        <header><span><i :class="config.icon"></i></span><div><small>{{ itemStatus(item) }}</small><h3>{{ patientName(item) }}</h3><p>{{ item.identificacion || item.paciente?.identificacion || 'Identificación no informada' }}</p></div><em>{{ formatDate(item.fecha_inicio || item.fecha_programada || item.fecha) }}</em></header>
        <div class="record-data"><div><small>Servicio / especialidad</small><strong>{{ item.servicio || item.especialidad || item.actividad || 'No informado' }}</strong></div><div><small>Profesional</small><strong>{{ item.profesional || item.usuario || 'Por asignar' }}</strong></div><div><small>Consultorio</small><strong>{{ item.consultorio || 'Por asignar' }}</strong></div><div><small>Orden</small><strong>#{{ item.id_orden_trabajo || item.orden_trabajo_id || '—' }}</strong></div></div>
        <footer>
          <button class="btn btn-sm btn-outline-primary" @click="openDetail(item)"><i class="ph ph-eye me-1"></i>Ver detalle</button>
          <button v-if="mode==='requests'" class="btn btn-sm btn-primary" @click="goAssign(item)"><i class="ph ph-calendar-plus me-1"></i>Asignar en agenda</button>
          <button v-if="mode==='unattended'" class="btn btn-sm btn-outline-danger" @click="openAction(item,'close')">Cierre administrativo</button>
          <router-link v-if="mode==='professional' && professionalSource==='appointments' && appointmentId(item)" class="btn btn-sm btn-primary" :to="`/consulta-externa/citas/${appointmentId(item)}`">Gestionar cita</router-link>
          <button v-if="mode==='professional' && professionalSource==='clinical' && !isDone(item)" class="btn btn-sm btn-success" @click="openAction(item,'complete')"><i class="ph ph-check me-1"></i>Completar actividad</button>
        </footer>
      </article>
    </section>
    <div v-if="meta.total" class="pagination-bar"><button class="btn btn-sm btn-outline-primary" :disabled="meta.page<=1" @click="changePage(-1)">Anterior</button><span>Página {{ meta.page }} de {{ meta.last }} · {{ meta.total }} registros</span><button class="btn btn-sm btn-outline-primary" :disabled="meta.page>=meta.last" @click="changePage(1)">Siguiente</button></div>

    <Teleport to="body"><div v-if="selected" class="control-layer" @mousedown.self="closeModal"><section class="control-modal"><header><div><small>CONTROL DE CITAS</small><h3>{{ action ? actionTitle : 'Detalle del registro' }}</h3></div><button class="btn-close" :disabled="saving" @click="closeModal"></button></header><form @submit.prevent="execute"><div class="modal-body"><div v-if="modalError" class="alert alert-danger">{{ modalError }}</div><div class="patient-box"><span>{{ initials(patientName(selected)) }}</span><div><small>PACIENTE</small><strong>{{ patientName(selected) }}</strong><p>{{ selected.servicio || selected.especialidad || selected.actividad }}</p></div></div><template v-if="action==='complete'"><label class="form-label mt-3">ID del registro maestro *</label><input v-model.number="form.masterId" type="number" min="1" class="form-control" required><label class="form-label mt-3">ID del registro clínico *</label><input v-model.number="form.recordId" type="number" min="1" class="form-control" required></template><template v-else-if="action==='close'"><p class="warning-box"><i class="ph ph-warning"></i>La cita quedará cerrada administrativamente y se registrará en su historial.</p></template><div v-else class="detail-grid"><div v-for="entry in detailEntries" :key="entry[0]"><small>{{ label(entry[0]) }}</small><strong>{{ entry[1] }}</strong></div></div></div><footer><button type="button" class="btn btn-outline-secondary" @click="closeModal">Cerrar</button><button v-if="action" class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Confirmar</button></footer></form></section></div></Teleport>
  </main>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{cerrarAdministrativamente,completarActividadClinica,consultarAgendaClinica,consultarAgendaProfesional,listarCitasNoAtendidas,listarSolicitudesCitas}from'@/services/intramural';
const route=useRoute(),router=useRouter(),items=ref([]),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),selected=ref(null),action=ref(''),modalError=ref(''),professionalSource=ref('appointments'),today=new Date().toISOString().slice(0,10),filters=reactive({estado:'hoy',buscar:'',desde:today,hasta:today,page:1,por_pagina:25}),meta=reactive({page:1,last:1,total:0}),form=reactive({masterId:'',recordId:''});
const mode=computed(()=>route.meta.appointmentMode||'requests'),configs={requests:{title:'Solicitudes de citas',help:'Asigne consultorio y confirme solicitudes pendientes.',icon:'ph ph-inbox',empty:'Sin solicitudes pendientes'},unattended:{title:'Citas no atendidas',help:'Revise casos vencidos, inasistencias y cierres pendientes.',icon:'ph ph-user-minus',empty:'Sin citas pendientes de revisión'},professional:{title:'Mi agenda clínica',help:'Actividades asignadas a su usuario, con filtros y paginación.',icon:'ph ph-stethoscope',empty:'Sin actividades clínicas'}},config=computed(()=>configs[mode.value]),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],itemId=i=>i.id_cita??i.id_solicitud??i.id_actividad??i.id,appointmentId=i=>i.id_cita??i.id,activityId=i=>i.id_actividad??i.id,patientName=i=>i.paciente?.nombre||i.paciente||i.nombre_paciente||'Paciente no informado',itemStatus=i=>i.estado_cita||i.estado?.nombre||i.estado||i.status_name||'Pendiente',isDone=i=>/realiz|complet|cerrad/i.test(itemStatus(i)),initials=v=>String(v||'P').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase(),formatDate=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(v).replace(' ','T'))):'Sin fecha',label=k=>String(k).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),detailEntries=computed(()=>Object.entries(selected.value||{}).filter(([,v])=>['string','number'].includes(typeof v)).slice(0,16)),actionTitle=computed(()=>action.value==='complete'?'Completar actividad clínica':'Cerrar cita administrativamente');
async function load(){loading.value=true;error.value='';try{if(mode.value==='requests')items.value=array(await listarSolicitudesCitas());if(mode.value==='unattended')items.value=array(await listarCitasNoAtendidas());if(mode.value==='professional'){if(professionalSource.value==='appointments'){let user={};try{user=JSON.parse(localStorage.getItem('user_info')||'{}')}catch{}const r=await consultarAgendaProfesional(user.id??user.id_user,{desde:filters.desde,hasta:filters.hasta});items.value=array(r?.citas||r?.agenda||r);Object.assign(meta,{page:1,last:1,total:items.value.length})}else{const r=await consultarAgendaClinica({estado:filters.estado,buscar:filters.buscar||undefined,por_pagina:filters.por_pagina,page:filters.page}),agenda=r?.agenda||r?.data?.agenda||{};items.value=array(agenda.data||agenda);Object.assign(meta,{page:agenda.meta?.pagina_actual||1,last:agenda.meta?.ultima_pagina||1,total:agenda.meta?.total||items.value.length})}}}catch(e){items.value=[];error.value=obtenerMensajeError(e)}finally{loading.value=false}}
function openDetail(i){if(i.id_cita){router.push(`/consulta-externa/citas/${i.id_cita}`);return}selected.value=i;action.value='';modalError.value=''}function openAction(i,a){selected.value=i;action.value=a;modalError.value='';Object.assign(form,{masterId:'',recordId:''})}function closeModal(){if(!saving.value){selected.value=null;action.value=''}}function goAssign(i){router.push({path:'/consulta-externa/agenda',query:{solicitud:itemId(i),paciente:i.id_paciente??i.paciente?.id??'',identificacion:i.identificacion??i.paciente?.identificacion??'',especialidad:i.id_especialidad??'',profesional:i.id_profesional??i.id_user??'',actividad:i.id_actividad??i.id_orden_de_servicio??'',fecha:i.fecha_inicio??i.fecha_programada??''}})}async function execute(){saving.value=true;modalError.value='';try{if(action.value==='close')await cerrarAdministrativamente(appointmentId(selected.value));if(action.value==='complete')await completarActividadClinica(activityId(selected.value),{id_master_registro:Number(form.masterId),id_registro:Number(form.recordId)});closeModal();notice.value='Acción realizada correctamente.';await load()}catch(e){modalError.value=obtenerMensajeError(e)}finally{saving.value=false}}function changePage(step){filters.page+=step;load()}onMounted(load)
</script>
<style scoped>.control-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#124c76,#148bac);color:#fff}.control-hero>div:last-child{display:flex;gap:.5rem}.control-hero span,.control-modal header small{font-size:.7rem;font-weight:800;letter-spacing:.08em}.control-hero h1{margin:.2rem 0;font-size:1.6rem}.control-hero p{margin:0;opacity:.82}.control-nav{display:flex;gap:.5rem;margin-top:1rem}.control-nav a{display:flex;align-items:center;gap:.4rem;padding:.55rem .75rem;border:1px solid #dce6ec;border-radius:.65rem;background:#fff;color:#586b7d;font-size:.72rem}.control-nav a.router-link-active{border-color:#75b9dc;background:#eef8fd;color:#2179a5}.filters{display:grid;grid-template-columns:220px 1fr auto;gap:.6rem;margin-top:1rem;padding:.8rem;border:1px solid #dfe7ed;border-radius:.75rem;background:#fff}.loading,.empty{display:grid;place-items:center;padding:4rem;text-align:center;color:#758594}.control-list{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem;margin-top:1rem}.control-list>article{overflow:hidden;border:1px solid #dfe7ed;border-radius:.8rem;background:#fff;box-shadow:0 6px 18px #183f5d0b}.control-list article>header{display:flex;align-items:center;gap:.65rem;padding:.8rem;border-bottom:1px solid #e7ecef}.control-list header>span{display:grid;place-items:center;width:39px;height:39px;border-radius:11px;background:#e8f4fb;color:#267da9}.control-list header>div{flex:1}.control-list small,.control-list h3,.control-list p{display:block;margin:0}.control-list header small{color:#27815d;font-size:.65rem;font-weight:800}.control-list h3{font-size:.86rem}.control-list p{color:#7a8997;font-size:.69rem}.control-list em{font-size:.67rem;font-style:normal}.record-data{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem;padding:.8rem}.record-data div{padding:.55rem;border-radius:.55rem;background:#f7f9fa}.record-data small,.record-data strong{display:block}.record-data small{color:#7e8d9a;font-size:.63rem}.record-data strong{font-size:.72rem}.control-list footer{display:flex;justify-content:flex-end;gap:.45rem;padding:.7rem .8rem;border-top:1px solid #e7ecef}.pagination-bar{display:flex;align-items:center;justify-content:center;gap:1rem;margin-top:1rem}.control-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:1rem;background:#071522bd}.control-modal{width:min(600px,100%);max-height:92vh;overflow:auto;border-radius:1rem;background:#fff}.control-modal>header{display:flex;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ed}.control-modal h3{margin:.1rem 0;font-size:1rem}.control-modal .modal-body{padding:1.2rem}.control-modal footer{display:flex;justify-content:flex-end;gap:.5rem;padding:1rem 1.2rem;border-top:1px solid #e3e9ed}.patient-box{display:flex;align-items:center;gap:.6rem;padding:.7rem;border-radius:.7rem;background:#f0f8fc}.patient-box>span{display:grid;place-items:center;width:40px;height:40px;border-radius:11px;background:#247da8;color:#fff;font-weight:800}.patient-box>div{flex:1}.patient-box small,.patient-box strong,.patient-box p{display:block;margin:0}.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem;margin-top:.8rem}.detail-grid div{padding:.6rem;border:1px solid #e2e8ec;border-radius:.55rem}.detail-grid small,.detail-grid strong{display:block;overflow-wrap:anywhere}.detail-grid small{color:#7c8b98;font-size:.63rem}.detail-grid strong{font-size:.72rem}.warning-box{display:flex;gap:.5rem;margin-top:1rem;padding:.75rem;border-radius:.65rem;background:#fff4e2;color:#9c641f}@media(max-width:800px){.control-list{grid-template-columns:1fr}}@media(max-width:600px){.control-hero{align-items:flex-start;flex-direction:column;gap:1rem}.filters,.record-data,.detail-grid{grid-template-columns:1fr}.control-nav{overflow:auto}}</style>
